@@ -69,6 +80,35 @@ void _collectModelEntry(
   if (window != null) windows[id] = window;
   final cap = _reportedMaxTokens(entry);
   if (cap != null) maxTokens[id] = cap;
+  final modalities = _reportedInputModalities(entry);
